-- The fixed selections of the specialisation benchmark's cells, a cell's name
-- as Cells names it, generated once and never edited by hand.  With $S
-- a checkout of https://github.com/Mikolaj/slop, $B the benchmark's
-- executable and T/forced.txt and T/summed.txt the tables it prints,
-- GHCRTS=-V0 $B and GHCRTS=-V0 $B --summed, groups is the output of
--
--   python3 $S/tools/NCG-battery/a2tcells.py cells --groups \
--     T/forced.txt T/summed.txt
--
-- one cell of each group, a group being the mode, the family, the operation,
-- the size and the kind, the views of a row its members, chosen by Python's
-- random.Random(1) over the groups in sorted order, and thin is
-- $S/tools/NCG-battery/pins/a2t-cells.txt, the battery's sample of forced
-- cells of small arrays whose call took 100 ns or less, to 1000 cells.
module CellLists (groups, thin) where

